ORG = {'@type':'Organization','@id':DOMAIN+'/#organization','name':'CDL Marketing','legalName':'CDL Management','url':DOMAIN+'/','telephone':'+1-660-665-3889','email':'caleb@cdl1.net'}

def write(path,title,description,body,schema=None):
 url=DOMAIN+path
 data=[ORG,{'@type':'WebSite','@id':DOMAIN+'/#website','name':'CDL Marketing','url':DOMAIN+'/'}, {'@type':'WebPage','@id':url+'#page','url':url,'name':title,'description':description,'isPartOf':{'@id':DOMAIN+'/#website'},'about':{'@id':DOMAIN+'/#organization'}}]
 if schema: data.extend(schema)
 if path != '/':
  name=re.sub('<[^>]+>','',title.split(' | ')[0])
  data.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':DOMAIN+'/'},{'@type':'ListItem','position':2,'name':name,'item':url}]})
 schema_json=json.dumps({'@context':'https://schema.org','@graph':data},ensure_ascii=False).replace('</','<\\/')
 out=f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{ESC(title)}</title><meta name="description" content="{ESC(description,quote=True)}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#f7f3ec"><meta property="og:type" content="website"><meta property="og:site_name" content="CDL Marketing"><meta property="og:title" content="{ESC(title,quote=True)}"><meta property="og:description" content="{ESC(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{DOMAIN}/assets/og-image.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{ESC(title,quote=True)}"><meta name="twitter:description" content="{ESC(description,quote=True)}"><meta name="twitter:image" content="{DOMAIN}/assets/og-image.jpg"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{schema_json}</script><script src="/assets/site.js" defer></script><script src="/assets/track.js" defer></script></head><body>{header()}<main id="main" tabindex="-1">{body}</main>{footer()}</body></html>'''
 if any(item.get('@type')=='Article' for item in data):
  out=out.replace('property="og:type" content="website"','property="og:type" content="article"')
  out=out.replace('</head>','<meta property="article:published_time" content="2026-10-30"></head>')
 out=out.replace('—',', ').replace(' – ',' to ')
 dest=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)
 PAGES.append(path)

