 city='<div class="field"><label for="city">City and state</label><input id="city" name="city" autocomplete="address-level2" required maxlength="160"></div>' if audit else ''
 return f'''<form class="lead-form" method="post" id="{'applyForm' if audit else 'leadForm'}" data-lead-form="{kind}"><div class="form-fields"><h3>{'Tell us about your showroom' if audit else 'Claim your free homepage design'}</h3><p class="muted">{'All fields are required except your website.' if audit else 'Required: business name, your name, email and business type.'}</p><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="160"></div><div class="field"><label for="showroom">{'Showroom' if audit else 'Business'} name</label><input id="showroom" name="showroom" autocomplete="organization" required maxlength="200"></div>{city}<div class="fields-row"><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="phone">Phone{' (optional)' if not audit else ''}</label><input id="phone" name="phone" type="tel" autocomplete="tel" {'required' if audit else ''} maxlength="40"></div></div><div class="field"><label for="website">Current website (optional)</label><input id="website" name="website" inputmode="url" autocomplete="url" maxlength="500" placeholder="yourshowroom.com"></div>{extra}<div class="hp" aria-hidden="true"><label for="company_website_hp">Leave this field blank</label><input id="company_website_hp" name="company_website_hp" tabindex="-1" autocomplete="off"></div><button class="btn" type="submit" disabled>{'Request my free growth audit' if audit else 'Send me my free design'} <span aria-hidden="true">→</span></button><p class="form-fine">By sending, you ask us to contact you about your request. We do not sell your details. <a href="/privacy/">Privacy policy</a>.</p><noscript><p>Please enable JavaScript to send this form, or <a href="mailto:caleb@cdl1.net">email caleb@cdl1.net</a>.</p></noscript></div><div class="form-message" role="status" aria-live="polite" aria-atomic="true"></div></form>'''

