def services():
 for slug,label,headline,desc,_ in SERVICES:
  d=DETAIL[slug]
  sections=''.join(f'<section id="part-{i}"><h2>{h}</h2><p>{p}</p></section>' for i,(h,p) in enumerate(d['sections'],1))
  related=''.join(f'<li><a href="/blog/{s}/">{next(x[2] for x in ARTICLE_INFO if x[0]==s)}</a></li>' for s in d['related'])
  body=subhero(label,d['h1'],d['intro'],'/services/'+slug+'/')+f'<section class="section"><div class="wrap article-layout"><p>{d["answer"]}</p><nav class="toc" aria-label="On this page"><b>On this page</b>'+''.join(f'<a href="#part-{i}">{h}</a>' for i,(h,p) in enumerate(d['sections'],1))+f'</nav>{sections}<aside><b>Part of the Showroom Growth System</b><p>Local SEO, CRM, managed ads and monthly adjustments. Setup is $1,500 once. Management starts at $1,750 per month, plus at least $1,500 in monthly advertising paid directly to platforms.</p><a href="/pricing/">See complete pricing and scope</a></aside><h2>Questions about {label.lower()}</h2>{faqs(d["faq"])}<h2>Keep reading</h2><ul>{related}</ul><p><a href="/services/">Explore all marketing services</a></p></div></section>'+cta()
  write('/services/'+slug+'/',label+' for Flooring Showrooms | CDL Marketing',d['intro'],body,[{'@type':'Service','name':label+' for flooring showrooms','serviceType':label,'provider':{'@id':DOMAIN+'/#organization'},'url':DOMAIN+'/services/'+slug+'/','description':d['intro']}])
 cards=''.join(f'<article class="service-card">{icon(s[4])}<h2>{s[1]}</h2><p>{s[3]}</p>{link("/services/"+s[0]+"/","Explore "+s[1].lower())}</article>' for s in SERVICES)
 write('/services/','Flooring Marketing Services | CDL Marketing','Local SEO, Google and Meta ads, flooring CRM and websites for independent flooring showrooms. Explore how the growth system works.',subhero('Services','One connected plan.<br>From search to showroom.','Local visibility, paid advertising and follow-up work better when they work together. Here is what we help with.','/services/')+'<section class="section"><div class="wrap cards two-cards">'+cards+'</div></section>'+cta())

def pricing():
 body=subhero('Pricing','The numbers.<br>Before the sales call.','One Showroom Growth System. A published management fee. Advertising paid directly to the platforms. Month-to-month.','/pricing/')+'''<section class="section"><div class="wrap article-layout"><h2>What you pay</h2><ul><li><strong>$1,500 one-time setup:</strong> CRM setup, website and search optimization, tracking and ad-account setup within the agreed scope.</li><li><strong>Monthly management from $1,750:</strong> the fee scales with advertising spend, as shown below.</li><li><strong>Advertising from $1,500 per month:</strong> client-funded, paid directly to Google and Meta, separate from management.</li></ul><div class="callout"><h3>Your starting budget</h3><p><strong>$3,250 per month ongoing</strong> at the minimum advertising level: $1,750 management + $1,500 advertising. The first month adds $1,500 setup, for <strong>$4,750</strong>.</p></div><h2>Management fees by ad spend</h2><table class="pricing-table"><caption class="sr-only">Monthly advertising spend and corresponding management fees</caption><thead><tr><th scope="col">Monthly advertising spend</th><th scope="col">Monthly management fee</th></tr></thead><tbody><tr><th scope="row">$1,500 minimum</th><td>$1,750</td></tr><tr><th scope="row">More than $1,500, up to $3,000</th><td>$2,500</td></tr><tr><th scope="row">More than $3,000, up to $5,000</th><td>$3,500</td></tr><tr><th scope="row">More than $5,000</th><td>$3,500 + 10% of the spend above $5,000</td></tr></tbody></table><p>For example, $6,000 in monthly advertising means a $3,600 management fee: $3,500 + 10% of $1,000.</p><h2>What the system includes</h2><ul><li>Local SEO and Google Business Profile optimization.</li><li>Useful website content and AI-search visibility work.</li><li>Your own flooring CRM with agreed lead capture and follow-up.</li><li>Managed Google and Meta advertising. The base scope includes three active Meta ads and one Google campaign.</li><li>Monthly market adjustments and reporting.</li></ul><p>We review your website, current systems, access and connections before agreeing on implementation. Higher advertising budgets and expanded campaigns need an agreed scope.</p><section id="guarantee"><h2>The 90-day lead guarantee</h2><p>If we do not deliver at least <strong>15 qualified local leads in your first 90 days</strong>, we continue working without an additional management fee until we do. We define a qualified lead with you before launch.</p><p>Advertising remains separate and is paid directly to the platforms. This guarantee covers qualified leads, not a particular search ranking, AI recommendation or number of sales.</p></section><h2>No long contract</h2><p>The service is month-to-month. Your specific scope and qualified-lead definition are agreed before starting.</p>'''+faqs([FAQ[4],FAQ[6],('Is the growth audit free?','Yes. The audit is free and there is no obligation to hire us. We review your showroom and discuss what would help before you decide.')])+'</div></section>'+cta()
 write('/pricing/','Flooring Marketing Pricing & Lead Guarantee | CDL Marketing','Published pricing: $1,500 setup, management from $1,750 per month, plus $1,500 minimum ad spend. Month-to-month. See scope and the 90-day lead guarantee.',body)

def about():
 body=subhero('About CDL','We know what it is like<br>to run a showroom.','CDL Marketing is part of CDL Management, based in Kirksville, Missouri. Caleb Foglesong and our team operate local businesses and do the marketing for them, too.','/about/')+'''<section class="section"><div class="wrap split"><div><span class="eyebrow">Our perspective</span><h2>Start with the work<br>behind the sale.</h2><p>Marketing is only part of the job. Someone has to answer the inquiry, help the homeowner, arrange the estimate and follow up on the quote. That is the world we work in.</p><p>Our flooring experience includes Kirksville Carpet One, Springfield Carpet One and Columbia Rug Carpet One in Peoria, along with ProSource wholesale showrooms. Our broader operating experience also includes other local service businesses.</p><p>We bring that practical perspective to local search, ads, websites and follow-up for independent flooring showrooms.</p></div><div class="quote-panel"><span class="eyebrow">Caleb Foglesong</span><h3>Owner, CDL Management</h3><p>Showroom experience.<br>Plain answers.<br>Work you can review.</p><small>We have not published independent client case studies or a verified client-results history. Our operating background is the evidence we can share today.</small></div></div></section><section class="section light"><div class="wrap narrow"><span class="eyebrow">How we judge the work</span><h2>Inquiries matter.<br>What happens next matters, too.</h2><p>We work toward more qualified conversations and sold jobs, rather than treating impressions or website visits as the finish line. When tracking is incomplete, we say so. A useful report should help you decide what to do next.</p><p>You can review the full fee structure and lead guarantee before talking with us. There is no long contract.</p>'''+link('/pricing/','See pricing and the lead guarantee')+'</div></section>'+cta()
 write('/about/','About Caleb Foglesong & CDL Marketing','Meet CDL Marketing, part of CDL Management in Kirksville, Missouri. Marketing for flooring showrooms, from a team that operates flooring showrooms.',body,[{'@type':'Person','name':'Caleb Foglesong','jobTitle':'Owner','worksFor':{'@id':DOMAIN+'/#organization'}}])

